// === src/errors.js ===
export class AppError extends Error {
  constructor(status, kode, pesan) { super(pesan); Object.assign(this, { status, kode }); }
}
// === src/repositories/produk.js ===
export function buatRepoMemori(awal = []) {
  const data = awal.map((p) => ({ ...p }));
  let nextId = data.length + 1;
  return {
    async semua() { return data.map((p) => ({ ...p })); },
    async cari(id) { const p = data.find((x) => x.id === id); return p ? { ...p } : null; },
    async cariNama(nama) { return data.find((x) => x.nama.toLowerCase() === nama.toLowerCase()) ?? null; },
    async tambah(p) { const baru = { id: nextId++, ...p }; data.push(baru); return { ...baru }; },
  };
}
// === src/services/produk.js ===
import { z } from 'zod';
import { AppError } from '../errors.js';
const ProdukBaru = z.object({ nama: z.string().trim().min(2), harga: z.number().int().positive() });
export function buatProdukService(repo) {
  return {
    daftar: () => repo.semua(),
    async detail(id) {
      const p = await repo.cari(id);
      if (!p) throw new AppError(404, 'PRODUK_TIDAK_ADA', `Produk ${id} tidak ada`);
      return p;
    },
    async tambah(masukan) {
      const h = ProdukBaru.safeParse(masukan);
      if (!h.success) throw new AppError(400, 'VALIDASI_GAGAL', 'Data produk tidak valid');
      if (await repo.cariNama(h.data.nama)) throw new AppError(409, 'NAMA_SUDAH_ADA', `${h.data.nama} sudah ada`);
      return repo.tambah(h.data);
    },
  };
}
// === src/routes/produk.js ===
import { Router } from 'express';
export function buatProdukRouter(service) {
  const router = Router();
  router.get('/', async (req, res) => res.json({ data: await service.daftar() }));
  router.get('/:id', async (req, res) => res.json({ data: await service.detail(Number(req.params.id)) }));
  router.post('/', async (req, res) => {
    const baru = await service.tambah(req.body);
    res.status(201).location(`${req.baseUrl}/${baru.id}`).json({ data: baru });
  });
  return router;
}
// === src/app.js ===
import express from 'express';
import { AppError } from './errors.js';
import { buatProdukRouter } from './routes/produk.js';
export function buatApp({ produkService }) {
  const app = express();
  app.use(express.json());
  app.use('/api/v1/produk', buatProdukRouter(produkService));
  app.use((req, res) => res.status(404).json({ error: { kode: 'JALUR_TIDAK_ADA', pesan: 'Jalur tidak ditemukan' } }));
  app.use((err, req, res, next) => {
    if (!(err instanceof AppError)) err = new AppError(500, 'KESALAHAN_SERVER', 'Terjadi kesalahan');
    res.status(err.status).json({ error: { kode: err.kode, pesan: err.message } });
  });
  return app;
}
// === main.js ===
import { buatRepoMemori } from './src/repositories/produk.js';
import { buatProdukService } from './src/services/produk.js';
import { buatApp } from './src/app.js';

const repo = buatRepoMemori([{ id: 1, nama: 'Kopi Susu', harga: 18000 }]);
const app = buatApp({ produkService: buatProdukService(repo) });
const server = app.listen(3000);

const u = 'http://localhost:3000/api/v1/produk';
const post = (body) => fetch(u, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
let r = await post({ nama: '  Es Teh  ', harga: 8000 });
console.log(r.status, r.headers.get('location'), (await r.json()).data);
for (const body of [{ nama: 'kopi susu', harga: 1 }, { nama: 'X', harga: 0 }]) {
  r = await post(body);
  console.log(r.status, (await r.json()).error.kode);
}
r = await fetch(u + '/7');
console.log(r.status, (await r.json()).error.pesan);
console.log((await (await fetch(u)).json()).data.length);
server.close();

